         trade.PositionClose(positionTicket);
         positionExists = false; // Marca que não tem mais posição, para possibilitar a abertura de uma nova
        }

      // Abre uma posição de compra se não existe uma posição
      if (!positionExists)
        {
         trade.Buy(lotSize, NULL, closePrice, 0, 0, "Comprado por cruzar SMA20");
